update public.questions set body_hi = 'भारत के वित्त आयोग के संबंध में निम्नलिखित कथनों पर विचार कीजिए:', explanation_hi = 'केवल कथन 4 सही है: 73वें और 74वें संशोधनों द्वारा संशोधित अनुच्छेद 280(3) के तहत वित्त आयोग राज्य वित्त आयोग की सिफ़ारिशों के आधार पर पंचायतों और नगरपालिकाओं के संसाधनों की पूर्ति के लिए राज्य की संचित निधि बढ़ाने के उपाय सुझाता है। कथन 1 अंतराल बदल देता है: आयोग का गठन हर चौथे नहीं, बल्कि हर पाँचवें वर्ष की समाप्ति पर होता है। कथन 2 गलत है: इसकी सिफ़ारिशें सलाहकारी हैं और केंद्र सरकार पर बाध्यकारी नहीं हैं। कथन 3 गलत है: वित्त आयोग अनुच्छेद 280 के तहत एक संवैधानिक निकाय है; 1951 का अधिनियम केवल इसके सदस्यों की योग्यताएँ और कार्य-प्रणाली तय करता है।', updated_at = now(), question_data = question_data || '{"statements_hi": ["वित्त आयोग का गठन राष्ट्रपति हर चौथे वर्ष, या आवश्यक समझें तो उससे पहले, करते हैं।", "वित्त आयोग की सिफ़ारिशें केंद्र सरकार पर बाध्यकारी होती हैं।", "वित्त आयोग वित्त आयोग (प्रकीर्ण उपबंध) अधिनियम, 1951 के तहत स्थापित एक सांविधिक (statutory) निकाय है।", "वित्त आयोग राज्य वित्त आयोग की सिफ़ारिशों के आधार पर, राज्य की पंचायतों और नगरपालिकाओं के संसाधनों की पूर्ति के लिए राज्य की संचित निधि बढ़ाने के आवश्यक उपाय सुझाता है।"]}'::jsonb where id = '8f950d2c-395f-4baf-91c0-1539f317fbd3' and exam_category = 'upsc' and jsonb_array_length(question_data->'statements') = 4 returning id;
update public.questions set body_hi = 'निम्नलिखित में से कौन-सा निकाय न तो संवैधानिक निकाय है और न ही सांविधिक निकाय?', explanation_hi = 'नीति आयोग 2015 में केंद्रीय मंत्रिमंडल के एक संकल्प द्वारा योजना आयोग के स्थान पर बनाया गया; इसका न तो संवैधानिक आधार है, न सांविधिक। बाकी तीनों सांविधिक निकाय हैं: राष्ट्रीय मानवाधिकार आयोग मानवाधिकार संरक्षण अधिनियम, 1993 के तहत; भारतीय प्रतिस्पर्धा आयोग प्रतिस्पर्धा अधिनियम, 2002 के तहत; और केंद्रीय सतर्कता आयोग, जो 1964 में एक कार्यकारी संकल्प से शुरू हुआ पर केंद्रीय सतर्कता आयोग अधिनियम, 2003 से सांविधिक है। पुराने नोट्स पढ़ने वाले के लिए यही आकर्षक गलत विकल्प है।', updated_at = now(), options = (select jsonb_agg(case when h.hi ? (o.v->>'id') then o.v || jsonb_build_object('body_hi', h.hi->>(o.v->>'id')) else o.v end order by o.ord) from jsonb_array_elements(options) with ordinality o(v, ord), (select '{"a": "केंद्रीय सतर्कता आयोग", "b": "भारतीय प्रतिस्पर्धा आयोग", "c": "नीति आयोग", "d": "राष्ट्रीय मानवाधिकार आयोग"}'::jsonb as hi) h) where id = '13ff77ef-bec3-4ba6-8543-415459b9d503' and exam_category = 'upsc' returning id;
update public.questions set body_hi = 'भारत के नियंत्रक-महालेखापरीक्षक (CAG) के संबंध में निम्नलिखित कथनों पर विचार कीजिए:', explanation_hi = 'केवल कथन 1 सही है: अनुच्छेद 148 के तहत CAG की नियुक्ति राष्ट्रपति करते हैं, और उसे केवल उसी रीति और उन्हीं आधारों पर हटाया जा सकता है जो उच्चतम न्यायालय के न्यायाधीश के लिए हैं। कथन 2 में संस्था बदल दी गई है: अनुच्छेद 151 के तहत केंद्र के लेखाओं से जुड़ी CAG की लेखापरीक्षा रिपोर्टें राष्ट्रपति को सौंपी जाती हैं, जो उन्हें संसद के प्रत्येक सदन के समक्ष रखवाते हैं; लोकसभा अध्यक्ष को नहीं। कथन 3 अनुच्छेद 148(4) को उलट देता है: पद छोड़ने के बाद CAG भारत सरकार या किसी राज्य सरकार के अधीन किसी और पद के योग्य नहीं होता; इससे उसकी स्वतंत्रता सुरक्षित रहती है।', updated_at = now(), question_data = question_data || '{"statements_hi": ["CAG की नियुक्ति राष्ट्रपति करते हैं और उसे केवल उसी रीति से तथा उन्हीं आधारों पर हटाया जा सकता है जो उच्चतम न्यायालय के न्यायाधीश को हटाने के लिए निर्धारित हैं।", "CAG केंद्र के लेखाओं से संबंधित अपनी लेखापरीक्षा रिपोर्टें लोकसभा अध्यक्ष को सौंपता है, जो उन्हें सदन के समक्ष रखवाते हैं।", "पद छोड़ने के बाद CAG भारत सरकार के अधीन आगे किसी पद के लिए पात्र होता है।"]}'::jsonb where id = '937e51bd-f1c5-4f11-bbc7-6287bff229d8' and exam_category = 'upsc' and jsonb_array_length(question_data->'statements') = 3 returning id;
update public.questions set body_hi = 'राज्य लोक सेवा आयोग के संबंध में निम्नलिखित कथनों पर विचार कीजिए:', explanation_hi = 'केवल कथन 2 सही है: अनुच्छेद 319(ग) के तहत राज्य लोक सेवा आयोग का अध्यक्ष UPSC का अध्यक्ष या सदस्य, या किसी दूसरे राज्य लोक सेवा आयोग का अध्यक्ष बन सकता है, पर सरकार के किसी और पद पर नहीं। कथन 1 गलत है: यद्यपि उनकी नियुक्ति राज्यपाल करते हैं, राज्य लोक सेवा आयोग के सदस्यों को केवल राष्ट्रपति हटा सकते हैं (अनुच्छेद 317); नियुक्ति और हटाने के अधिकार का यह अंतर एक प्रिय जाल है।', updated_at = now(), question_data = question_data || '{"statements_hi": ["राज्य लोक सेवा आयोग के किसी सदस्य को राज्यपाल पद से हटा सकते हैं।", "राज्य लोक सेवा आयोग का अध्यक्ष UPSC के अध्यक्ष या सदस्य के रूप में नियुक्ति के लिए पात्र है।"]}'::jsonb where id = '939c03a5-e781-498a-bd06-bf58f5ae2ae3' and exam_category = 'upsc' and jsonb_array_length(question_data->'statements') = 2 returning id;
update public.questions set body_hi = 'संघ लोक सेवा आयोग (UPSC) के संबंध में निम्नलिखित कथनों पर विचार कीजिए:', explanation_hi = 'तीनों कथन सही हैं: अनुच्छेद 320(3)(ग) अनुशासनिक मामलों में परामर्श अनिवार्य करता है; अनुच्छेद 320(4) अनुच्छेद 16(4) के तहत किए गए आरक्षण को इसकी परामर्शी भूमिका से बाहर रखता है; और अनुच्छेद 323 के तहत आयोग हर वर्ष राष्ट्रपति को रिपोर्ट देता है, जो उसे एक ज्ञापन के साथ संसद के समक्ष रखते हैं जिसमें उन मामलों का कारण बताया जाता है जहाँ इसकी सलाह नहीं मानी गई।', updated_at = now(), question_data = question_data || '{"statements_hi": ["भारत सरकार के अधीन सिविल हैसियत में सेवा करने वाले व्यक्ति को प्रभावित करने वाले अनुशासनिक मामलों पर UPSC से परामर्श किया जाता है।", "अनुच्छेद 16(4) के तहत पिछड़े वर्गों के पक्ष में नियुक्तियों या पदों के आरक्षण पर UPSC से परामर्श नहीं किया जाता।", "UPSC अपने कार्य की वार्षिक रिपोर्ट राष्ट्रपति को प्रस्तुत करता है।"]}'::jsonb where id = '17ebba84-fc4e-47ca-9059-c503c4c07353' and exam_category = 'upsc' and jsonb_array_length(question_data->'statements') = 3 returning id;
update public.questions set body_hi = 'कमज़ोर वर्गों के लिए राष्ट्रीय आयोगों के संबंध में निम्नलिखित कथनों पर विचार कीजिए:', explanation_hi = 'केवल कथन 1 सही है: 102वें संशोधन ने अनुच्छेद 338ख जोड़ा। कथन 2 गलत है: 65वें संशोधन (1990) ने अनुसूचित जातियों और अनुसूचित जनजातियों का एक संयुक्त राष्ट्रीय आयोग बनाया; अलग राष्ट्रीय अनुसूचित जनजाति आयोग (अनुच्छेद 338क) 89वें संशोधन (2003) से बना। कथन 3 गलत है: राष्ट्रीय अल्पसंख्यक आयोग, राष्ट्रीय अल्पसंख्यक आयोग अधिनियम, 1992 के तहत एक सांविधिक निकाय है। कथन 4 गलत है: राष्ट्रीय अनुसूचित जाति आयोग के अध्यक्ष की नियुक्ति राष्ट्रपति अपने हस्ताक्षर और मुद्रा सहित अधिपत्र द्वारा करते हैं (अनुच्छेद 338(3))।', updated_at = now(), question_data = question_data || '{"statements_hi": ["102वें संशोधन अधिनियम, 2018 द्वारा राष्ट्रीय पिछड़ा वर्ग आयोग को संवैधानिक दर्जा दिया गया।", "राष्ट्रीय अनुसूचित जनजाति आयोग को 65वें संशोधन अधिनियम, 1990 द्वारा एक अलग निकाय के रूप में बनाया गया।", "राष्ट्रीय अल्पसंख्यक आयोग एक संवैधानिक निकाय है।", "राष्ट्रीय अनुसूचित जाति आयोग के अध्यक्ष की नियुक्ति प्रधानमंत्री करते हैं।"]}'::jsonb where id = '53c4c9fa-4b09-45fc-8964-6fcc71adad8f' and exam_category = 'upsc' and jsonb_array_length(question_data->'statements') = 4 returning id;
update public.questions set body_hi = 'निम्नलिखित कथनों पर विचार कीजिए:', explanation_hi = 'कथन-I गलत है: अनुच्छेद 148 केवल इतना कहता है कि CAG की नियुक्ति राष्ट्रपति अपने हस्ताक्षर और मुद्रा सहित अधिपत्र द्वारा करेंगे; कोई चयन समिति निर्धारित नहीं है। कथन-II सही है: अनुच्छेद 148(3) के तहत CAG का वेतन और सेवा-शर्तें संसद तय करती है (अब CAG (कर्तव्य, शक्तियाँ और सेवा-शर्तें) अधिनियम, 1971 के तहत), और नियुक्ति के बाद उनमें उसके अहित में बदलाव नहीं किया जा सकता।', updated_at = now(), question_data = question_data || '{"assertion_hi": "भारत के नियंत्रक-महालेखापरीक्षक की नियुक्ति राष्ट्रपति, प्रधानमंत्री की अध्यक्षता वाली एक समिति की सिफ़ारिश पर करते हैं।", "reason_hi": "नियंत्रक-महालेखापरीक्षक का वेतन और अन्य सेवा-शर्तें संसद निर्धारित करती है।"}'::jsonb where id = '784808c6-3408-4d2d-b107-a51fe549613a' and exam_category = 'upsc' returning id;
update public.questions set body_hi = 'भारत के संविधान के निर्माण के संबंध में निम्नलिखित कथनों पर विचार कीजिए:', explanation_hi = 'केवल कथन 1 सही है: संविधान सभा 1946 में कैबिनेट मिशन योजना के तहत बनी। कथन 2 पदाधिकारियों को बदल देता है: प्रारूप समिति के अध्यक्ष डॉ. बी.आर. आंबेडकर थे, जबकि डॉ. राजेंद्र प्रसाद संविधान सभा के अध्यक्ष थे। कथन 3 दो तिथियों को मिला देता है: संविधान 26 नवंबर 1949 को अपनाया गया और 26 जनवरी 1950 को लागू हुआ।', updated_at = now(), question_data = question_data || '{"statements_hi": ["संविधान सभा का गठन 1946 की कैबिनेट मिशन योजना द्वारा बनाई गई व्यवस्था के तहत हुआ।", "डॉ. राजेंद्र प्रसाद संविधान सभा की प्रारूप समिति के अध्यक्ष थे।", "संविधान सभा ने भारत का संविधान 26 जनवरी 1950 को अपनाया।"]}'::jsonb where id = '3c77493d-9d95-4292-8a93-249f88bc702d' and exam_category = 'upsc' and jsonb_array_length(question_data->'statements') = 3 returning id;
update public.questions set body_hi = 'भारत के संविधान में संशोधन की प्रक्रिया के संबंध में निम्नलिखित कथनों पर विचार कीजिए:', explanation_hi = 'कथन 1 और 3 सही हैं। अनुच्छेद 368(2) के परंतुक के तहत सातवीं अनुसूची की सूचियों (और कुछ अन्य संघीय प्रावधानों) से जुड़े संशोधनों के लिए आधे राज्यों का अनुसमर्थन भी चाहिए। 24वें संशोधन (1971) के बाद राष्ट्रपति के लिए विधिवत पारित संविधान संशोधन विधेयक पर स्वीकृति देना अनिवार्य है। कथन 2 गलत है: मौलिक अधिकारों में संशोधन केवल संसद के विशेष बहुमत से होता है; वे परंतुक में गिनाए गए उन प्रावधानों में नहीं हैं जिनके लिए राज्यों का अनुसमर्थन चाहिए। उनके महत्त्व के कारण यह गलत धारणा आम है।', updated_at = now(), question_data = question_data || '{"statements_hi": ["सातवीं अनुसूची की किसी भी सूची को प्रभावित करने वाले संशोधन के लिए संसद के विशेष बहुमत के साथ-साथ कम से कम आधे राज्यों के विधानमंडलों का अनुसमर्थन भी आवश्यक है।", "भाग III के मौलिक अधिकारों में संशोधन के लिए कम से कम आधे राज्यों के विधानमंडलों का अनुसमर्थन आवश्यक है।", "अनुच्छेद 368 के तहत विधिवत पारित संविधान संशोधन विधेयक पर राष्ट्रपति स्वीकृति देने के लिए बाध्य हैं; वे न तो स्वीकृति रोक सकते हैं, न ही उसे पुनर्विचार के लिए लौटा सकते हैं।"]}'::jsonb where id = '20ad9fbc-2011-46a7-8aeb-192c4e49cd91' and exam_category = 'upsc' and jsonb_array_length(question_data->'statements') = 3 returning id;
update public.questions set body_hi = 'भारत में नागरिकता के संबंध में निम्नलिखित कथनों पर विचार कीजिए:', explanation_hi = 'कथन 2 और 3 सही हैं: अनुच्छेद 11 संसद को नागरिकता को विनियमित करने का अधिकार देता है, और नागरिकता अधिनियम, 1955 के तहत स्वेच्छा से किसी विदेशी देश की नागरिकता लेने पर भारतीय नागरिकता समाप्त हो जाती है। कथन 1 गलत है: संविधान का भाग II (अनुच्छेद 5-11) केवल यह बताता है कि संविधान लागू होने के समय कौन नागरिक था; उसके बाद नागरिकता प्राप्त करना और खोना संसद द्वारा बनाए गए नागरिकता अधिनियम, 1955 से नियंत्रित होता है।', updated_at = now(), question_data = question_data || '{"statements_hi": ["संविधान स्वयं अपने लागू होने के बाद नागरिकता प्राप्त करने और समाप्त होने के प्रावधान निर्धारित करता है।", "अनुच्छेद 11 संसद को नागरिकता प्राप्त करने और समाप्त करने के संबंध में कोई भी प्रावधान बनाने का अधिकार देता है।", "कोई भारतीय नागरिक जो स्वेच्छा से किसी दूसरे देश की नागरिकता प्राप्त कर लेता है, वह भारत का नागरिक नहीं रहता।"]}'::jsonb where id = '8fe53581-0fea-44b6-8e6c-8a5dfcf1331b' and exam_category = 'upsc' and jsonb_array_length(question_data->'statements') = 3 returning id;
update public.questions set body_hi = 'उन स्रोतों के संबंध में निम्नलिखित कथनों पर विचार कीजिए जिनसे भारत के संविधान की विशेषताएँ ली गईं:', explanation_hi = 'कथन 1, 2 और 4 सही हैं: नीति निदेशक तत्व आयरलैंड के संविधान से, संशोधन की प्रक्रिया (और राज्यसभा सदस्यों का निर्वाचन) दक्षिण अफ़्रीका से, और आपातकाल में मौलिक अधिकारों का निलंबन जर्मनी के वाइमर संविधान से लिया गया। कथन 3 गलत है: मौलिक कर्तव्य अमेरिका से नहीं, पूर्व सोवियत संघ (USSR) के संविधान से लिए गए।', updated_at = now(), question_data = question_data || '{"statements_hi": ["राज्य के नीति निदेशक तत्व आयरलैंड के संविधान से लिए गए।", "संविधान संशोधन की प्रक्रिया दक्षिण अफ़्रीका के संविधान से ली गई।", "मौलिक कर्तव्य संयुक्त राज्य अमेरिका के संविधान से लिए गए।", "आपातकाल के दौरान मौलिक अधिकारों का निलंबन जर्मनी के वाइमर संविधान से लिया गया।"]}'::jsonb where id = '690eaa3f-1908-4f71-b6a6-51e8bf379acc' and exam_category = 'upsc' and jsonb_array_length(question_data->'statements') = 4 returning id;
update public.questions set body_hi = 'भारत के संविधान की प्रस्तावना के संबंध में निम्नलिखित कथनों पर विचार कीजिए:', explanation_hi = 'केवल कथन 1 सही है: 42वें संशोधन (1976) ने ''समाजवादी'', ''पंथनिरपेक्ष'' और ''अखंडता'' शब्द जोड़े। कथन 2 गलत है: प्रस्तावना भारत को संपूर्ण प्रभुत्व-संपन्न, समाजवादी, पंथनिरपेक्ष, लोकतंत्रात्मक गणराज्य कहती है; ''संघीय'' शब्द न प्रस्तावना में है, न संविधान में कहीं। कथन 3 मामलों को बदल देता है: बेरुबारी (1960) में न्यायालय ने कहा कि प्रस्तावना संविधान का भाग नहीं है; केशवानंद भारती (1973) में न्यायालय ने इसे संविधान का भाग माना।', updated_at = now(), question_data = question_data || '{"statements_hi": ["''समाजवादी'', ''पंथनिरपेक्ष'' और ''अखंडता'' शब्द 42वें संशोधन अधिनियम, 1976 द्वारा प्रस्तावना में जोड़े गए।", "प्रस्तावना भारत को एक संघीय गणराज्य घोषित करती है।", "बेरुबारी यूनियन मामले (1960) में उच्चतम न्यायालय ने माना कि प्रस्तावना संविधान का भाग है।"]}'::jsonb where id = '10a5a38b-95b4-4bfd-9ed4-67c574f2ed64' and exam_category = 'upsc' and jsonb_array_length(question_data->'statements') = 3 returning id;
update public.questions set body_hi = 'भारत के संविधान की अनुसूचियों के संबंध में निम्नलिखित कथनों पर विचार कीजिए:', explanation_hi = 'केवल कथन 1 सही है: 52वें संशोधन (1985) द्वारा जोड़ी गई दसवीं अनुसूची में दल-बदल विरोधी प्रावधान हैं। कथन 2 गलत है: आठवीं अनुसूची में मूल रूप से 14 भाषाएँ थीं; बाद के संशोधनों से इनकी संख्या 22 हुई।', updated_at = now(), question_data = question_data || '{"statements_hi": ["दसवीं अनुसूची में दल-बदल के आधार पर संसद और राज्य विधानमंडलों के सदस्यों की अयोग्यता के प्रावधान हैं।", "संविधान लागू होने के समय आठवीं अनुसूची में मूल रूप से 22 भाषाएँ थीं।"]}'::jsonb where id = '4e903fa3-a3d9-4bb8-9059-a759cbf828da' and exam_category = 'upsc' and jsonb_array_length(question_data->'statements') = 2 returning id;
update public.questions set body_hi = 'भारत के संविधान के निम्नलिखित भागों और उनकी विषय-वस्तु पर विचार कीजिए:', explanation_hi = 'तीनों कथन सही हैं: भाग XI (अनुच्छेद 245-263) संघ-राज्य संबंधों से, भाग XIV (अनुच्छेद 308-323) संघ और राज्यों के अधीन सेवाओं से, जिनमें लोक सेवा आयोग भी शामिल हैं, और भाग XV (अनुच्छेद 324-329क) निर्वाचन से संबंधित है।', updated_at = now(), question_data = question_data || '{"statements_hi": ["भाग XI संघ और राज्यों के बीच संबंधों से संबंधित है।", "भाग XIV संघ और राज्यों के अधीन सेवाओं से संबंधित है।", "भाग XV निर्वाचन से संबंधित है।"]}'::jsonb where id = '447bcc95-fe9b-4cb5-b909-fbd080e4cafa' and exam_category = 'upsc' and jsonb_array_length(question_data->'statements') = 3 returning id;
update public.questions set body_hi = 'नागरिकता (संशोधन) अधिनियम, 2019 के संबंध में निम्नलिखित कथनों पर विचार कीजिए:', explanation_hi = 'केवल कथन 1 सही है: अधिनियम तीनों देशों के इन छह समुदायों पर लागू है। कथन 2 अंतिम तिथि बदल देता है: अधिनियम उन पर लागू है जो 31 दिसंबर 2014 को या उससे पहले भारत आए। कथन 3 संख्या बदल देता है: इनके लिए देशीयकरण (naturalisation) हेतु निवास की अवधि ग्यारह वर्ष से घटाकर पाँच वर्ष की गई, सात नहीं। नागरिकता (संशोधन) नियम मार्च 2024 में अधिसूचित हुए। यह अधिनियम असम, मेघालय, मिज़ोरम और त्रिपुरा के छठी अनुसूची वाले जनजातीय क्षेत्रों, और इनर लाइन परमिट वाले क्षेत्रों पर लागू नहीं होता।', updated_at = now(), question_data = question_data || '{"statements_hi": ["यह अफ़ग़ानिस्तान, बांग्लादेश और पाकिस्तान के हिंदू, सिख, बौद्ध, जैन, पारसी और ईसाई समुदायों के लोगों को नागरिकता के लिए पात्र बनाता है।", "अधिनियम के तहत पात्र होने के लिए ऐसे लोगों का 31 दिसंबर 2016 को या उससे पहले भारत आना आवश्यक है।", "इसने ऐसे लोगों के देशीयकरण के लिए आवश्यक निवास की अवधि ग्यारह वर्ष से घटाकर सात वर्ष कर दी।"]}'::jsonb where id = '3315aa30-63e8-43f3-a8fe-b767e51f6c08' and exam_category = 'upsc' and jsonb_array_length(question_data->'statements') = 3 returning id;
update public.questions set body_hi = 'संविधान संशोधन अधिनियमों और उनकी विषय-वस्तु के निम्नलिखित युग्मों पर विचार कीजिए:', explanation_hi = 'केवल युग्म 1 सही है: 61वें संशोधन (1988) ने मतदान की आयु घटाकर 18 वर्ष की। युग्म 2 गलत है: दल-बदल विरोधी कानून 52वें संशोधन (1985) से जुड़ा; 86वें संशोधन (2002) ने प्रारंभिक शिक्षा को मौलिक अधिकार (अनुच्छेद 21क) बनाया। युग्म 3 गलत है: GST 101वें संशोधन (2016) से आया; 91वें संशोधन (2003) ने मंत्रिपरिषद का आकार सीमित किया और दसवीं अनुसूची से दल के विभाजन (split) का अपवाद हटाया। युग्म 4 गलत है: 73वाँ संशोधन पंचायतों से संबंधित है; नगरपालिकाएँ 74वें संशोधन से आईं।', updated_at = now(), question_data = question_data || '{"list_1_hi": ["1. 61वाँ संशोधन अधिनियम", "2. 86वाँ संशोधन अधिनियम", "3. 91वाँ संशोधन अधिनियम", "4. 73वाँ संशोधन अधिनियम"], "list_2_hi": ["मतदान की आयु 21 से घटाकर 18 वर्ष करना", "दल-बदल विरोधी कानून (दसवीं अनुसूची)", "वस्तु एवं सेवा कर (GST)", "नगरपालिकाएँ"]}'::jsonb where id = 'bce8a8fd-4403-43c5-a60b-095e298ba49e' and exam_category = 'upsc' and jsonb_array_length(question_data->'list_1') = 4 returning id;
update public.questions set body_hi = 'संविधान सभा की निम्नलिखित समितियों में से किसकी अध्यक्षता जवाहरलाल नेहरू ने की?', explanation_hi = 'जवाहरलाल नेहरू ने संघ शक्ति समिति (और संघ संविधान समिति तथा राज्य समिति) की अध्यक्षता की। प्रारूप समिति की अध्यक्षता डॉ. बी.आर. आंबेडकर ने, प्रांतीय संविधान समिति की सरदार वल्लभभाई पटेल ने, और प्रक्रिया नियम समिति की डॉ. राजेंद्र प्रसाद ने की।', updated_at = now(), options = (select jsonb_agg(case when h.hi ? (o.v->>'id') then o.v || jsonb_build_object('body_hi', h.hi->>(o.v->>'id')) else o.v end order by o.ord) from jsonb_array_elements(options) with ordinality o(v, ord), (select '{"a": "प्रारूप समिति", "b": "संघ शक्ति समिति", "c": "प्रांतीय संविधान समिति", "d": "प्रक्रिया नियम समिति"}'::jsonb as hi) h) where id = 'ee930ac8-1e1a-4176-9ae1-477ff1adf851' and exam_category = 'upsc' returning id;
update public.questions set body_hi = 'संघ और उसके राज्यक्षेत्र के संबंध में निम्नलिखित कथनों पर विचार कीजिए:', explanation_hi = 'चारों कथन सही हैं। अनुच्छेद 3 का परंतुक राष्ट्रपति की सिफ़ारिश और राज्य विधानमंडल को संदर्भ अनिवार्य करता है, जिसके विचार संसद पर बाध्यकारी नहीं हैं। अनुच्छेद 4(2) कहता है कि अनुच्छेद 2 और 3 के तहत बने कानून अनुच्छेद 368 के प्रयोजन के लिए संशोधन नहीं माने जाते, इसलिए वे साधारण बहुमत से पारित होते हैं। बेरुबारी यूनियन संदर्भ (1960) में न्यायालय ने कहा कि अनुच्छेद 3 के तहत संसद की शक्ति में भारतीय क्षेत्र किसी विदेशी राज्य को सौंपना शामिल नहीं है, इसके लिए अनुच्छेद 368 के तहत संशोधन चाहिए; इसीलिए 9वाँ संशोधन (1960) हुआ।', updated_at = now(), question_data = question_data || '{"statements_hi": ["नए राज्य के गठन या किसी मौजूदा राज्य की सीमाओं में परिवर्तन का विधेयक संसद में केवल राष्ट्रपति की सिफ़ारिश पर ही पेश किया जा सकता है।", "ऐसे विधेयक की सिफ़ारिश करने से पहले राष्ट्रपति को उसे संबंधित राज्य के विधानमंडल को एक निश्चित अवधि में अपने विचार देने के लिए भेजना होता है, पर संसद उन विचारों से बाध्य नहीं है।", "अनुच्छेद 2 और 3 के तहत बना कानून, पहली और चौथी अनुसूची में संशोधन करने के बावजूद, अनुच्छेद 368 के प्रयोजन के लिए संविधान का संशोधन नहीं माना जाता।", "बेरुबारी यूनियन मामले (1960) में उच्चतम न्यायालय ने कहा कि भारतीय क्षेत्र किसी विदेशी देश को सौंपने के लिए अनुच्छेद 368 के तहत संविधान संशोधन आवश्यक है।"]}'::jsonb where id = '187286b2-5e6a-4bd0-89b2-acf07dcd8942' and exam_category = 'upsc' and jsonb_array_length(question_data->'statements') = 4 returning id;
update public.questions set body_hi = 'भारत के संविधान के संबंध में निम्नलिखित कथनों पर विचार कीजिए:', explanation_hi = 'केवल कथन 1 सही है: भारत का संविधान किसी भी संप्रभु देश का सबसे लंबा लिखित संविधान है। कथन 2 गलत है: मूल संविधान में 395 अनुच्छेद, 22 भाग और 8 अनुसूचियाँ थीं; संशोधनों से अनुसूचियों की संख्या बढ़कर 12 हुई।', updated_at = now(), question_data = question_data || '{"statements_hi": ["यह किसी भी संप्रभु देश का विश्व में सबसे लंबा लिखित संविधान है।", "मूल संविधान में बारह अनुसूचियाँ थीं।"]}'::jsonb where id = '24a01528-9e45-4eb8-9b4f-4e4bf2f45c42' and exam_category = 'upsc' and jsonb_array_length(question_data->'statements') = 2 returning id;
update public.questions set body_hi = 'भारत के संविधान की निम्नलिखित अनुसूचियों में से कौन-सी राज्यसभा में सीटों के आवंटन से संबंधित है?', explanation_hi = 'चौथी अनुसूची राज्यों और केंद्रशासित प्रदेशों के बीच राज्यसभा की सीटें बाँटती है। दूसरी अनुसूची संवैधानिक पदाधिकारियों के वेतन-भत्तों से, छठी अनुसूची असम, मेघालय, त्रिपुरा और मिज़ोरम के जनजातीय क्षेत्रों के प्रशासन से, और आठवीं अनुसूची मान्यता प्राप्त भाषाओं से संबंधित है।', updated_at = now(), options = (select jsonb_agg(case when h.hi ? (o.v->>'id') then o.v || jsonb_build_object('body_hi', h.hi->>(o.v->>'id')) else o.v end order by o.ord) from jsonb_array_elements(options) with ordinality o(v, ord), (select '{"a": "दूसरी अनुसूची", "b": "चौथी अनुसूची", "c": "छठी अनुसूची", "d": "आठवीं अनुसूची"}'::jsonb as hi) h) where id = '36097191-be76-459b-b558-496177536dbd' and exam_category = 'upsc' returning id;
update public.questions set body_hi = 'निम्नलिखित में से कौन-सा संविधान संशोधन अधिनियम, अपने द्वारा किए गए बहुत अधिक परिवर्तनों के कारण, ''लघु संविधान'' (mini-Constitution) कहलाता है?', explanation_hi = 'स्वर्ण सिंह समिति की सिफ़ारिशों पर बना 42वाँ संशोधन अधिनियम, 1976 ''लघु संविधान'' कहलाता है: अन्य बहुत-से बदलावों के साथ इसने प्रस्तावना में संशोधन किया, मौलिक कर्तव्य जोड़े और पाँच विषयों को समवर्ती सूची में डाला। 44वें संशोधन (1978) ने इसके कई बदलावों को पलट दिया।', updated_at = now(), options = (select jsonb_agg(case when h.hi ? (o.v->>'id') then o.v || jsonb_build_object('body_hi', h.hi->>(o.v->>'id')) else o.v end order by o.ord) from jsonb_array_elements(options) with ordinality o(v, ord), (select '{"a": "24वाँ संशोधन अधिनियम", "b": "44वाँ संशोधन अधिनियम", "c": "73वाँ संशोधन अधिनियम", "d": "42वाँ संशोधन अधिनियम"}'::jsonb as hi) h) where id = 'a23167b3-9fec-45aa-b3b2-c5bc6765f128' and exam_category = 'upsc' returning id;
update public.questions set body_hi = 'निम्नलिखित कथनों पर विचार कीजिए:', explanation_hi = 'कथन-I गलत है: केशवानंद भारती (1973) में उच्चतम न्यायालय ने कहा कि मूल ढाँचे की सीमा में प्रस्तावना का अनुच्छेद 368 के तहत संशोधन हो सकता है, और इसका एक बार संशोधन हुआ भी है: 42वें संशोधन (1976) से, जिसने ''समाजवादी'', ''पंथनिरपेक्ष'' और ''अखंडता'' शब्द जोड़े। कथन-II सही है: उसी मामले ने बेरुबारी संदर्भ (1960) के मत को पलटते हुए कहा कि प्रस्तावना संविधान का भाग है।', updated_at = now(), question_data = question_data || '{"assertion_hi": "भारत के संविधान की प्रस्तावना का अनुच्छेद 368 के तहत संशोधन नहीं किया जा सकता।", "reason_hi": "प्रस्तावना संविधान का एक भाग है।"}'::jsonb where id = '9cb5180d-0c98-4da6-8659-abe0b8b1d6c6' and exam_category = 'upsc' returning id;
update public.questions set body_hi = 'भारत के संविधान की अनुसूचियों के संबंध में निम्नलिखित कथनों पर विचार कीजिए:', explanation_hi = 'चारों कथन सही हैं। पहले संशोधन (1951) ने भूमि-सुधार कानूनों की रक्षा के लिए नौवीं अनुसूची बनाई; 73वें और 74वें संशोधनों (1992) ने ग्यारहवीं (पंचायतों के 29 विषय) और बारहवीं (नगरपालिकाओं के 18 विषय) अनुसूचियाँ जोड़ीं; और समवर्ती सूची में मूल रूप से 47 विषय थे (अब 52 हैं, मुख्यतः इसलिए कि 42वें संशोधन ने शिक्षा और वन जैसे विषय राज्य सूची से इसमें डाले)।', updated_at = now(), question_data = question_data || '{"statements_hi": ["नौवीं अनुसूची संविधान (पहला संशोधन) अधिनियम, 1951 द्वारा जोड़ी गई।", "ग्यारहवीं अनुसूची में पंचायतों के कार्यक्षेत्र के 29 विषय हैं।", "बारहवीं अनुसूची में नगरपालिकाओं के कार्यक्षेत्र के 18 विषय हैं।", "सातवीं अनुसूची की समवर्ती सूची में मूल रूप से 47 विषय थे।"]}'::jsonb where id = 'c3755626-524b-4087-9898-ce338a87000d' and exam_category = 'upsc' and jsonb_array_length(question_data->'statements') = 4 returning id;
update public.questions set body_hi = 'भारत के संविधान में राजभाषा संबंधी प्रावधानों के संबंध में निम्नलिखित कथनों पर विचार कीजिए:', explanation_hi = 'कथन 1, 3 और 4 सही हैं। अनुच्छेद 343(1) देवनागरी लिपि में हिंदी को संघ की राजभाषा बनाता है; राजभाषा अधिनियम, 1963 (1967 में संशोधित) हिंदी के साथ अंग्रेज़ी के अनिश्चित काल तक प्रयोग की अनुमति देता है; और अनुच्छेद 348(1) संसद के अन्यथा उपबंध करने तक उच्चतम न्यायालय और उच्च न्यायालयों की भाषा अंग्रेज़ी रखता है। कथन 2 गलत है: संविधान किसी भी भाषा को राष्ट्रभाषा घोषित नहीं करता; भाग XVII केवल राजभाषा की बात करता है।', updated_at = now(), question_data = question_data || '{"statements_hi": ["अनुच्छेद 343 देवनागरी लिपि में हिंदी को संघ की राजभाषा घोषित करता है।", "संविधान हिंदी को भारत की राष्ट्रभाषा घोषित करता है।", "राजभाषा अधिनियम, 1963 संघ के शासकीय प्रयोजनों के लिए हिंदी के अतिरिक्त अंग्रेज़ी के प्रयोग को बिना किसी समय-सीमा के जारी रखने की अनुमति देता है।", "अनुच्छेद 348 के तहत, जब तक संसद विधि द्वारा अन्यथा उपबंध न करे, उच्चतम न्यायालय और प्रत्येक उच्च न्यायालय की सभी कार्यवाहियाँ अंग्रेज़ी में होंगी।"]}'::jsonb where id = '66ce2cb6-eccf-4f48-8bb1-d0674150a372' and exam_category = 'upsc' and jsonb_array_length(question_data->'statements') = 4 returning id;
update public.questions set body_hi = 'निम्नलिखित कथनों पर विचार कीजिए:', explanation_hi = 'दोनों कथन सही हैं और कथन-II, कथन-I की व्याख्या करता है। संविधान न अमेरिकी संविधान जितना कठोर है, न ब्रिटिश जितना लचीला, क्योंकि इसमें संशोधन की तीन विधियाँ हैं: साधारण बहुमत से (अनुच्छेद 368 के बाहर, जैसे नए राज्य बनाना), अनुच्छेद 368 के तहत विशेष बहुमत से, और संघीय प्रावधानों के लिए विशेष बहुमत के साथ आधे राज्यों के अनुसमर्थन से।', updated_at = now(), question_data = question_data || '{"assertion_hi": "भारत के संविधान को कठोरता और लचीलेपन का मिश्रण कहा जाता है।", "reason_hi": "संविधान के कुछ प्रावधानों का संशोधन संसद के साधारण बहुमत से हो सकता है, कुछ के लिए विशेष बहुमत चाहिए, और कुछ के लिए आधे राज्य विधानमंडलों का अनुसमर्थन भी चाहिए।"}'::jsonb where id = '78d0af74-5963-4681-82fc-ce5f34b4c0be' and exam_category = 'upsc' returning id;
update public.questions set body_hi = 'भारत निर्वाचन आयोग के संबंध में निम्नलिखित कथनों पर विचार कीजिए:', explanation_hi = 'केवल कथन 1 सही है: निर्वाचन आयोग अनुच्छेद 324 के तहत एक संवैधानिक निकाय है। कथन 2 गलत है: निर्वाचन आयोग संसद, राज्य विधानमंडलों और राष्ट्रपति तथा उपराष्ट्रपति के पदों के निर्वाचन का अधीक्षण करता है, पर पंचायतों और नगरपालिकाओं के चुनाव राज्य निर्वाचन आयोग कराते हैं (अनुच्छेद 243ट और 243यक)।', updated_at = now(), question_data = question_data || '{"statements_hi": ["भारत निर्वाचन आयोग एक संवैधानिक निकाय है।", "भारत निर्वाचन आयोग राज्यों में पंचायतों और नगरपालिकाओं के चुनाव कराता है।"]}'::jsonb where id = '137ca5cc-1cc7-49f1-86bc-da71c299d1e4' and exam_category = 'upsc' and jsonb_array_length(question_data->'statements') = 2 returning id;
update public.questions set body_hi = 'मुख्य निर्वाचन आयुक्त और अन्य निर्वाचन आयुक्त (नियुक्ति, सेवा-शर्तें और पदावधि) अधिनियम, 2023 के संबंध में निम्नलिखित कथनों पर विचार कीजिए:', explanation_hi = 'केवल कथन 1 सही है: अधिनियम एक चयन समिति का प्रावधान करता है, जिसमें प्रधानमंत्री (अध्यक्ष), प्रधानमंत्री द्वारा नामित एक केंद्रीय कैबिनेट मंत्री, और लोकसभा में विपक्ष के नेता (या सबसे बड़े विपक्षी दल के नेता) हैं। कथन 2 गलत है: मुख्य न्यायाधीश केवल अनूप बरनवाल (2023) में दी गई अंतरिम व्यवस्था में थे, जिसकी जगह यह अधिनियम आया। कथन 3 गलत है: खोज समिति (Search Committee) की अध्यक्षता केंद्रीय विधि और न्याय मंत्री करते हैं। कथन 4 गलत है: मुख्य निर्वाचन आयुक्त को केवल उसी रीति और उन्हीं आधारों पर हटाया जा सकता है जो उच्चतम न्यायालय के न्यायाधीश के लिए हैं।', updated_at = now(), question_data = question_data || '{"statements_hi": ["अधिनियम के तहत चयन समिति में प्रधानमंत्री, प्रधानमंत्री द्वारा नामित एक केंद्रीय कैबिनेट मंत्री और लोकसभा में विपक्ष के नेता होते हैं।", "भारत के मुख्य न्यायाधीश अधिनियम के तहत चयन समिति के सदस्य हैं।", "चयन समिति के लिए पाँच नामों का पैनल तैयार करने वाली खोज समिति की अध्यक्षता कैबिनेट सचिव करते हैं।", "मुख्य निर्वाचन आयुक्त को राष्ट्रपति चयन समिति की सिफ़ारिश पर हटा सकते हैं।"]}'::jsonb where id = 'aa16c676-f59f-4b5d-b426-0a4f698f99af' and exam_category = 'upsc' and jsonb_array_length(question_data->'statements') = 4 returning id;
update public.questions set body_hi = 'संविधान के अनुच्छेदों और उनकी विषय-वस्तु के निम्नलिखित युग्मों पर विचार कीजिए:', explanation_hi = 'चारों युग्म सही हैं: ये भाग XV (निर्वाचन) के मुख्य प्रावधान हैं। अनुच्छेद 324 निर्वाचन का अधीक्षण निर्वाचन आयोग को सौंपता है, अनुच्छेद 325 बिना भेदभाव के एक साधारण निर्वाचक नामावली का प्रावधान करता है, अनुच्छेद 326 वयस्क मताधिकार का प्रावधान करता है, और अनुच्छेद 329 चुनाव याचिका के अलावा निर्वाचन के मामलों में न्यायालयों के हस्तक्षेप पर रोक लगाता है।', updated_at = now(), question_data = question_data || '{"list_1_hi": ["1. अनुच्छेद 324", "2. अनुच्छेद 325", "3. अनुच्छेद 326", "4. अनुच्छेद 329"], "list_2_hi": ["निर्वाचन का अधीक्षण, निदेशन और नियंत्रण निर्वाचन आयोग में निहित होना", "धर्म, मूलवंश, जाति या लिंग के आधार पर किसी व्यक्ति को निर्वाचक नामावली में शामिल होने के अयोग्य न ठहराना", "लोकसभा और राज्य विधानसभाओं के चुनाव वयस्क मताधिकार के आधार पर होना", "निर्वाचन संबंधी मामलों में न्यायालयों के हस्तक्षेप पर रोक"]}'::jsonb where id = '4fec29a2-6e61-4cc6-b212-a3493f6d505f' and exam_category = 'upsc' and jsonb_array_length(question_data->'list_1') = 4 returning id;
update public.questions set body_hi = 'लोक प्रतिनिधित्व अधिनियम, 1951 के संबंध में निम्नलिखित कथनों पर विचार कीजिए:', explanation_hi = 'तीनों कथन सही हैं: धारा 8(3) दोषसिद्धि की तिथि से और रिहाई के बाद छह वर्ष तक अयोग्यता निर्धारित करती है; लिली थॉमस (2013) ने वर्तमान विधायकों को धारा 8(4) की सुरक्षा समाप्त कर दी, जिससे दोषसिद्धि होते ही अयोग्यता लागू होती है; और 1996 में जोड़ी गई धारा 33(7) आम चुनाव में किसी उम्मीदवार को अधिकतम दो निर्वाचन क्षेत्रों तक सीमित करती है।', updated_at = now(), question_data = question_data || '{"statements_hi": ["किसी अपराध में दोषसिद्ध होकर कम से कम दो वर्ष के कारावास की सज़ा पाने वाला व्यक्ति दोषसिद्धि की तिथि से और रिहाई के बाद आगे छह वर्ष तक अयोग्य रहता है।", "लिली थॉमस बनाम भारत संघ (2013) में उच्चतम न्यायालय ने अधिनियम की धारा 8(4) को रद्द कर दिया, जो तीन महीने में अपील करने पर दोषसिद्ध वर्तमान विधायकों को पद पर बने रहने देती थी।", "कोई उम्मीदवार लोकसभा के आम चुनाव में दो से अधिक निर्वाचन क्षेत्रों से चुनाव नहीं लड़ सकता।"]}'::jsonb where id = '3ee8dfae-78cb-4674-85c2-0b75e7900266' and exam_category = 'upsc' and jsonb_array_length(question_data->'statements') = 3 returning id;
update public.questions set body_hi = 'निम्नलिखित कथनों पर विचार कीजिए:', explanation_hi = 'कथन-I सही है: पीपुल्स यूनियन फ़ॉर सिविल लिबर्टीज़ बनाम भारत संघ (2013) में उच्चतम न्यायालय के निर्णय के बाद निर्वाचन आयोग ने 2013 में NOTA की शुरुआत की। कथन-II गलत है: वर्तमान कानून में NOTA मतों का कोई निर्वाचन-मूल्य नहीं है; यदि NOTA को सबसे अधिक मत मिलें, तब भी उम्मीदवारों में सबसे अधिक मत पाने वाला उम्मीदवार निर्वाचित घोषित होता है।', updated_at = now(), question_data = question_data || '{"assertion_hi": "भारतीय चुनावों में ''इनमें से कोई नहीं'' (NOTA) का विकल्प उच्चतम न्यायालय के एक निर्णय के बाद शुरू किया गया।", "reason_hi": "यदि किसी निर्वाचन क्षेत्र में NOTA को सबसे अधिक मत मिलें, तो वहाँ फिर से चुनाव कराना अनिवार्य है।"}'::jsonb where id = '7928147f-a8e6-4671-853b-4926a4528a54' and exam_category = 'upsc' returning id;
